using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Authorization;
using Microsoft.AspNetCore.Components.Web;
using sv_956c1d65873e497da053f7c48a1358ba.Client;
using System.Security.Claims;

namespace sv_956c1d65873e497da053f7c48a1358ba;

internal sealed class HardcodedAuthenticationStateProvider
    : AuthenticationStateProvider, IDisposable
{
    private static readonly AuthenticationState _authState = CreateAuthState();

    private readonly PersistentComponentState _persistentState;
    private readonly PersistingComponentStateSubscription _subscription;

    public HardcodedAuthenticationStateProvider(PersistentComponentState persistentState)
    {
        _persistentState = persistentState;
        _subscription = persistentState.RegisterOnPersisting(OnPersistingAsync, RenderMode.InteractiveWebAssembly);
    }

    public override Task<AuthenticationState> GetAuthenticationStateAsync()
        => Task.FromResult(_authState);

    private Task OnPersistingAsync()
    {
        var user = _authState.User;
        var userInfo = new UserInfo
        {
            Email = user.FindFirstValue(ClaimTypes.Email) ?? string.Empty,
            Roles = user.FindAll(ClaimTypes.Role).Select(c => c.Value).ToArray()
        };

        _persistentState.PersistAsJson(nameof(UserInfo), userInfo);
        return Task.CompletedTask;
    }

    private static AuthenticationState CreateAuthState()
    {
        var claims = new List<Claim>
        {
            new(ClaimTypes.Name, "bob@example.com"),
            new(ClaimTypes.Email, "bob@example.com"),
            new(ClaimTypes.Role, "User"),
            new(ClaimTypes.Role, "Editor"),
        };

        var identity = new ClaimsIdentity(claims, "Hardcoded");
        return new AuthenticationState(new ClaimsPrincipal(identity));
    }

    public void Dispose() => _subscription.Dispose();
}

